// Obtain the library-owned query string. Do not modify or free the returned pointer.
const char* q = LiGetLaunchUrlQueryParameters();
// It may be NULL or empty depending on host/features. We simply fetch it for coverage.
(void)q; // no-op use

// streamConfig must be a valid, writable pointer allocated by the caller (provided by the fuzzer runtime)
LiInitializeStreamConfiguration(streamConfig);
// Mark as initialized for subsequent API calls (LiStartConnection requires this)
FUZZ_SET_ATTR_INT(streamConfig, "initialized", 1);

// drCallbacks must be a valid, writable pointer allocated by the caller (provided by the fuzzer runtime)
LiInitializeVideoCallbacks(drCallbacks);
// Track initialization for downstream validation
FUZZ_SET_ATTR_INT(drCallbacks, "initialized", 1);

// arCallbacks must be a valid, writable pointer allocated by the caller (provided by the fuzzer runtime)
LiInitializeAudioCallbacks(arCallbacks);
// Track initialization for downstream validation
FUZZ_SET_ATTR_INT(arCallbacks, "initialized", 1);

// clCallbacks must be a valid, writable pointer allocated by the caller (provided by the fuzzer runtime)
LiInitializeConnectionCallbacks(clCallbacks);
// Track initialization for downstream validation
FUZZ_SET_ATTR_INT(clCallbacks, "initialized", 1);

// serverInfo must be a valid, writable pointer allocated by the caller (provided by the fuzzer runtime)
LiInitializeServerInformation(serverInfo);
// Track initialization for downstream validation
FUZZ_SET_ATTR_INT(serverInfo, "initialized", 1);

// Enforce preconditions: serverInfo and streamConfig must be initialized via helper functions
if (FUZZ_GET_ATTR_INT(serverInfo, "initialized") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(streamConfig, "initialized") != 1) { FUZZ_BAIL(); }
// We pass NULL for optional callback structures in this harness to keep ownership simple.
// Flags are fuzzed but kept small to avoid undefined capability combinations.
int drFlags = (int)(*FUZZ_PARAM(unsigned int) & 0x3);
int arFlags = (int)(*FUZZ_PARAM(unsigned int) & 0x3);
void* renderContext = nullptr;
void* audioContext = nullptr;
int rc = LiStartConnection(serverInfo, streamConfig, /*clCallbacks*/ nullptr, /*drCallbacks*/ nullptr, /*arCallbacks*/ nullptr,
                           renderContext, drFlags, audioContext, arFlags);
// Track connection state globally. 0 indicates success/active.
if (rc == 0) {
    FUZZ_SET_ATTR_INT_GLOBAL("conn_active", 1);
} else {
    // Leave conn_active unchanged or mark inactive on failure
    FUZZ_SET_ATTR_INT_GLOBAL("conn_active", 0);
}

// This function is not thread-safe with LiStartConnection(). We enforce a simple lifecycle:
// Only stop if a connection is currently active in our tracked state.
int active = FUZZ_GET_ATTR_INT_GLOBAL("conn_active");
if (active != 1) { FUZZ_BAIL(); }
LiStopConnection();
// Update lifecycle tracking
FUZZ_SET_ATTR_INT_GLOBAL("conn_active", 0);

// Asynchronously interrupts a pending LiStartConnection(). There is no strict precondition we can verify
// here without internal state about a pending start. We just invoke it to cover the call path.
LiInterruptConnection();

// stage should be a STAGE_* constant; we provide a small range of integers.
int stage = (int)(*FUZZ_PARAM(unsigned int) % 32);
const char* name = LiGetStageName(stage);
(void)name; // do not modify or free

// Must be called only between LiStartConnection() and LiStopConnection().
if (FUZZ_GET_ATTR_INT_GLOBAL("conn_active") != 1) { FUZZ_BAIL(); }
// Pointers are provided by the fuzzer runtime and guaranteed non-null and writable per harness contract.
bool ok = LiGetEstimatedRttInfo(estimatedRtt, estimatedRttVariance);
(void)ok; // The function may fail depending on transport; no assertion required.

// An active connection must exist implicitly for delivery.
if (FUZZ_GET_ATTR_INT_GLOBAL("conn_active") != 1) { FUZZ_BAIL(); }
short dx = (short)(*FUZZ_PARAM(unsigned int));
short dy = (short)(*FUZZ_PARAM(unsigned int));
int rc = LiSendMouseMoveEvent(dx, dy);
(void)rc;

// Requires an active connection.
if (FUZZ_GET_ATTR_INT_GLOBAL("conn_active") != 1) { FUZZ_BAIL(); }
// Positive reference plane dimensions
short refW = (short)((*FUZZ_PARAM(unsigned short) % 32767u) + 1u);
short refH = (short)((*FUZZ_PARAM(unsigned short) % 32767u) + 1u);
// Coordinates in the reference plane (wrap into range)
short x = (short)((*FUZZ_PARAM(unsigned int)) % (unsigned int)refW);
short y = (short)((*FUZZ_PARAM(unsigned int)) % (unsigned int)refH);
int rc = LiSendMousePositionEvent(x, y, refW, refH);
(void)rc;

// Must not be called concurrently with LiSendMousePositionEvent(); single-threaded harness satisfies this.
if (FUZZ_GET_ATTR_INT_GLOBAL("conn_active") != 1) { FUZZ_BAIL(); }
short dx = (short)(*FUZZ_PARAM(unsigned int));
short dy = (short)(*FUZZ_PARAM(unsigned int));
short refW = (short)((*FUZZ_PARAM(unsigned short) % 32767u) + 1u);
short refH = (short)((*FUZZ_PARAM(unsigned short) % 32767u) + 1u);
int rc = LiSendMouseMoveAsMousePositionEvent(dx, dy, refW, refH);
(void)rc;

// Requires an active connection.
if (FUZZ_GET_ATTR_INT_GLOBAL("conn_active") != 1) { FUZZ_BAIL(); }
char action = (char)((*FUZZ_PARAM(unsigned int)) % 2); // PRESS or RELEASE
int button = (int)((*FUZZ_PARAM(unsigned int)) % 5);   // LEFT..X2 enumerated range
