import random
from typing import List, Tuple

# Generator for XML data expected by xml_search, xml_applist, xml_modelist, xml_status
# Goal: produce valid, small XML documents covering different schemas the parsers might expect.
# - Application list: <apps><app id="...">Name</app>...</apps>
# - Model list: <modes><mode width=".." height=".." refresh=".."/></modes>
# - Status: <root><status>...</status></root> with numeric or textual status
# - Mixed: include comments, CDATA, namespaces, attributes ordering, whitespace variety
# The fuzzer stubs pass arbitrary buffers; we provide well-formed XML to drive code paths.

XML_DECL = '<?xml version="1.0" encoding="UTF-8"?>\n'

APP_NAMES = [
    "Steam",
    "Notepad",
    "Game One",
    "Game Two",
    "Browser",
    "Media Player",
    "ÄppÜnicode",
]

def _rand_id(r: random.Random) -> int:
    # Typical app IDs are positive ints; include edge-y but valid values
    return r.choice([1, 2, 3, 10, 42, 100, 256, 65535, r.randint(4, 10000)])

def _xml_escape(text: str) -> str:
    return (
        text.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
            .replace("'", "&apos;")
    )

def _gen_app_list_xml(r: random.Random) -> str:
    count = r.randint(1, 8)
    # Sometimes include a namespace or attributes on root
    ns = " xmlns=\"urn:moonlight:apps\"" if r.random() < 0.3 else ""
    attrs = []
    if r.random() < 0.3:
        attrs.append(f' count="{count}"')
    root_attrs = ns + ("".join(attrs))
    parts = [XML_DECL, f"<apps{root_attrs}>\n"]
    if r.random() < 0.4:
        parts.append("  <!-- Application list -->\n")
    for i in range(count):
        name = _xml_escape(r.choice(APP_NAMES))
        app_id = _rand_id(r)
        # optional extra attributes to exercise parser robustness
        extra = []
        if r.random() < 0.4:
            extra.append(f' visible="{r.choice(["true","false"])}"')
        if r.random() < 0.2:
            extra.append(f' category="{_xml_escape(r.choice(["game","tool","media"]))}"')
        parts.append(f"  <app id=\"{app_id}\"{''.join(extra)}>{name}</app>\n")
    parts.append("</apps>\n")
    return "".join(parts)

def _gen_mode_list_xml(r: random.Random) -> str:
    count = r.randint(1, 8)
    root_name = r.choice(["modes", "displayModes"])  # cover alternative roots
    parts = [XML_DECL, f"<{root_name}>\n"]
    if r.random() < 0.4:
        parts.append("  <!-- Display modes list -->\n")
    # Common resolutions and refresh rates
    resolutions = [(1280,720),(1920,1080),(2560,1440),(3840,2160),(1024,768),(1366,768)]
    refreshes = [24, 30, 50, 59, 60, 75, 90, 120, 144, 165]
    for i in range(count):
        if r.random() < 0.5:
            w,h = r.choice(resolutions)
        else:
            w = r.choice([800,1024,1280,1366,1600,1920,2560,3440,3840])
            h = r.choice([600,720,768,900,1080,1200,1440,1600,2160])
        if r.random() < 0.2:
            # Generate portrait to see parser assumptions
            w,h = h,w
        refresh = r.choice(refreshes)
        # Some entries self-closing, some with explicit close
        if r.random() < 0.7:
            parts.append(f"  <mode width=\"{w}\" height=\"{h}\" refresh=\"{refresh}\"/>\n")
        else:
            parts.append(f"  <mode width=\"{w}\" height=\"{h}\" refresh=\"{refresh}\"></mode>\n")
    parts.append(f"</{root_name}>\n")
    return "".join(parts)

def _gen_status_xml(r: random.Random) -> str:
    # Provide different shapes where status could be attribute, text, or nested
    style = r.randint(0, 3)
    if style == 0:
        return XML_DECL + f"<root><status>{r.choice([0,1,200,404,500])}</status></root>\n"
    elif style == 1:
        return XML_DECL + f"<status code=\"{r.choice([0,1,200,404,500])}\">OK</status>\n"
    elif style == 2:
        return XML_DECL + "<root>\n  <!-- Mixed content -->\n  <meta>v1</meta>\n  <status>success</status>\n</root>\n"
    else:
        return XML_DECL + "<response>\n  <details><![CDATA[All good <no parse>]]></details>\n  <status>1</status>\n</response>\n"

def _gen_searchable_xml(r: random.Random) -> Tuple[str, str]:
    # Build a doc containing a variety of nodes for xml_search
    nodes = [
        ("title", _xml_escape(r.choice(["Hello","Moonlight","Status","AppList"]))),
        ("version", _xml_escape(r.choice(["1.0","2.0","3.1"]))),
        ("status", str(r.choice([0,1,200,404]))),
        ("message", _xml_escape(r.choice(["OK","Error","Pending"]))),
    ]
    # Randomly add duplicate node names
    if r.random() < 0.5:
        nodes.append(("status", str(r.choice(["ok","warn","fail"]))))
    parts = [XML_DECL, "<doc>\n"]
    for n,v in nodes:
        if r.random() < 0.3:
            parts.append(f"  <{n} attr=\"x\">{v}</{n}>\n")
        else:
            parts.append(f"  <{n}>{v}</{n}>\n")
    parts.append("</doc>\n")
    # Choose a node name likely to exist, or occasionally a non-existent one
    if r.random() < 0.85:
        node = r.choice([n for n,_ in nodes])
    else:
        node = r.choice(["nonexistent","foo","bar"]) 
    return ("".join(parts), node)

def _mix_docs(r: random.Random) -> str:
    # Optionally concatenate multiple docs to exercise len and embedded docs handling
    docs: List[str] = []
    # Choose 1-3 documents
    for _ in range(1, r.randint(1, 3)+1):
        choice = r.random()
        if choice < 0.33:
            docs.append(_gen_app_list_xml(r))
        elif choice < 0.66:
            docs.append(_gen_mode_list_xml(r))
        else:
            docs.append(_gen_status_xml(r))
    sep = "\n" + (" " * r.randint(0, 3))
    return sep.join(docs)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a schema to target based on seed
    schema = r.random()
    if schema < 0.30:
        xml = _gen_app_list_xml(r)
    elif schema < 0.60:
        xml = _gen_mode_list_xml(r)
    elif schema < 0.80:
        xml = _gen_status_xml(r)
    else:
        # Produce a doc aimed at xml_search consumers, but still valid XML
        doc, node = _gen_searchable_xml(r)
        # Prepend a comment that hints at the node name, increasing chance search hits
        xml = doc
        if r.random() < 0.7:
            xml = f"<!-- search:{node} -->\n" + xml
    # Occasionally return a mix of documents to stress len parsing while still valid per-buffer
    if r.random() < 0.25:
        mixed = _mix_docs(r)
        # Ensure we keep within 4096 bytes
        candidate = (xml + "\n" + mixed)
        xml = candidate[:4096]
    # Enforce size cap
    data = xml.encode('utf-8')[:4096]
    return data

import random
import string
from typing import List, Tuple

# Generator for valid and interesting URLs suitable for http_request() fuzz stubs.
# Produces a bytes object containing a UTF-8, NUL-free string. The fuzzer stub
# will append a NUL terminator on its side.

SCHEMES = [
    "http",
    "https",
]

HOST_LABEL_CHARS = string.ascii_lowercase + string.digits
TLDs = [
    "com", "net", "org", "io", "dev", "local", "lan",
]

# Common ports used by Moonlight/Sunshine and general web services
PORTS = [80, 443, 47984, 47989, 47990, 48010, 48000, 65535, 1]

# Common paths and API endpoints relevant to GameStream/Moonlight ecosystems
PATH_SEGMENTS = [
    "", "index.html", "api", "json", "xml", "launch", "resume",
    "pair", "unpair", "serverinfo", "applist", "modelist", "status",
    "stream", "rtsp", "token", "cert", "ping",
]

QUERY_KEYS = [
    "appId", "mode", "width", "height", "fps", "bitrate", "codec",
    "hdr", "sops", "localaudio", "gamepadMask", "session", "streamId",
    "q", "v", "t", "lang",
]

CODECS = ["h264", "hevc", "av1"]
BOOLS = ["0", "1", "true", "false"]

IPV4_EXAMPLES = [
    "127.0.0.1", "0.0.0.0", "192.168.0.1", "10.0.0.2", "172.16.0.10"
]

IPV6_EXAMPLES = [
    "::1", "fe80::1", "2001:db8::1", "fd00::1234"
]

USERPASS = [
    ("user", "pass"),
    ("moon", "light"),
    ("admin", "admin"),
]

PATH_EXT = ["", ".html", ".xml", ".json"]

SAFE_PCHAR = string.ascii_letters + string.digits + "-._~"
EXTRA_PCHAR = "!$&'()*+,;=:@"  # allowed in path/query with %-encoding when needed


def _rand(r: random.Random, seq: List):
    return seq[r.randrange(len(seq))]


def _host_label(r: random.Random, min_len=1, max_len=10) -> str:
    n = r.randint(min_len, max_len)
    # label must not start or end with hyphen; keep simple
    s = ''.join(r.choice(HOST_LABEL_CHARS) for _ in range(n))
    return s


def _hostname(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.35:
        # domain name
        labels = [_host_label(r) for _ in range(r.randint(2, 3))]
        tld = _rand(r, TLDs)
        return '.'.join(labels + [tld])
    elif choice < 0.7:
        # IPv4 literal
        if r.random() < 0.5:
            return _rand(r, IPV4_EXAMPLES)
        return '.'.join(str(r.randint(0, 255)) for _ in range(4))
    else:
        # IPv6 literal in brackets
        addr = _rand(r, IPV6_EXAMPLES)
        return f"[{addr}]"


def _path_segment(r: random.Random) -> str:
    base = _rand(r, PATH_SEGMENTS)
    if base == "":
        # random alnum segment
        base = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(r.randint(3, 10)))
    if r.random() < 0.5:
        base += _rand(r, PATH_EXT)
    return base


def _random_pchars(r: random.Random, min_len=0, max_len=10) -> str:
    length = r.randint(min_len, max_len)
    # include some reserved chars; URL will stay valid in path/query
    alphabet = SAFE_PCHAR + EXTRA_PCHAR
    return ''.join(r.choice(alphabet) for _ in range(length))


def _query_pair(r: random.Random) -> Tuple[str, str]:
    k = _rand(r, QUERY_KEYS)
    if k in ("width", "height", "fps", "bitrate"):
        v = str(r.choice([30, 60, 90, 120, 720, 1080, 1440, 2160, 10000, 20000]))
    elif k in ("hdr", "sops", "localaudio"):
        v = _rand(r, BOOLS)
    elif k == "codec":
        v = _rand(r, CODECS)
    elif k == "gamepadMask":
        v = hex(r.choice([0x0, 0x1, 0x3, 0xF, 0xFFFF]))
    elif k == "appId":
        v = str(r.randint(1, 1000000))
    else:
        v = _random_pchars(r, 0, 12)
    return (k, v)


def _maybe_userinfo(r: random.Random) -> str:
    if r.random() < 0.2:
        u, p = _rand(r, USERPASS)
        # Allow optional password
        if r.random() < 0.5:
            return f"{u}@"
        return f"{u}:{p}@"
    return ""


def _build_url(r: random.Random) -> str:
    scheme = _rand(r, SCHEMES)
    userinfo = _maybe_userinfo(r)
    host = _hostname(r)
    # Optional port; https frequently 443, http 80, but vary
    port = ''
    if r.random() < 0.6:
        chosen = _rand(r, PORTS)
        # Avoid default port duplication sometimes
        if not (scheme == 'http' and chosen == 80) and not (scheme == 'https' and chosen == 443):
            port = f":{chosen}"
        elif r.random() < 0.2:
            port = f":{chosen}"
    # Build path
    segments = []
    seg_count = r.randint(0, 4)
    for _ in range(seg_count):
        segments.append(_path_segment(r))
    path = '/' + '/'.join(segments) if segments else '/'
    # Maybe add trailing slash
    if r.random() < 0.3 and not path.endswith('/'):
        path += '/'
    # Query
    query = ''
    if r.random() < 0.85:
        qpairs = []
        # Optionally include library-provided launch params hint key
        # but keep generic for validity
        for _ in range(r.randint(1, 6)):
            k, v = _query_pair(r)
            qpairs.append(f"{k}={v}")
        # Occasionally add duplicate keys and empty values
        if r.random() < 0.3:
            dupk, dupv = _query_pair(r)
            qpairs.append(f"{dupk}={dupv}")
        if r.random() < 0.2:
            qpairs.append(_rand(r, QUERY_KEYS) + "=")
        query = '?' + '&'.join(qpairs)
    # Fragment (harmless for HTTP request, but valid URL)
    fragment = ''
    if r.random() < 0.15:
        fragment = '#' + _random_pchars(r, 0, 8)
    return f"{scheme}://{userinfo}{host}{port}{path}{query}{fragment}"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build a mix of variants to cover different code paths in HTTP client:
    # - IPv4/IPv6, default/explicit ports, userinfo, paths, queries
    url = _build_url(r)
    # Ensure size <= 4096 bytes
    if len(url) > 4096:
        url = url[:4096]
    # The fuzzer stub copies string and appends NUL; avoid embedded NULs here
    return url.encode('utf-8', errors='ignore')
